(function(){'use strict';
const M=BatchCardMath,$=id=>document.getElementById(id),shipping=ActivityViews.shipping,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Number.isFinite(n)?n.toLocaleString('ru-RU',{maximumFractionDigits:2}):'—',copy=x=>JSON.parse(JSON.stringify(x));
const labels={craft:'Крафт',purchase:'Закупка',luxury:'Роскошь'},city=c=>c==='Black Market'?'Чёрный рынок':c||'Город не указан';
let store,error='',selected='',filter='all',archive=false,query='',stage='all';
try{store=M.create(localStorage);}catch(e){error=e.message;}
const panel=document.createElement('section');panel.id='batch-cards-panel';panel.className='panel batch-board';panel.dataset.foldIgnore='';
panel.innerHTML='<div class="section-heading"><div><h2>Карточки партий</h2><p>Закупки, получение, перевозка и продажа — по городам.</p></div><span id="batch-server" class="tag"></span></div><div class="batch-board-controls"><label class="batch-search">Поиск<input id="batch-search" type="search" maxlength="200" placeholder="Предмет, город или заметка"></label><label>Этап<select id="batch-stage"><option value="all">Все этапы</option><option value="purchase">Осталось купить</option><option value="pickup">Можно забрать</option><option value="delivery">Нужно доставить</option><option value="production">Можно изготовить</option><option value="sale">Есть что продать</option><option value="complete">Завершено</option></select></label><label>Показывать<select id="batch-kind"><option value="all">Все партии</option><option value="craft">Крафт</option><option value="purchase">Закупки</option><option value="luxury">Роскошь</option></select></label><label class="refining-check"><input id="batch-archive" type="checkbox"> Показать архив</label><button type="button" class="button" id="batch-clear-filters">Сбросить фильтры</button><span id="batch-match-count" class="hint" role="status" aria-live="polite"></span></div><p class="hint">Нажмите «Вести партию» в расчёте крафта, закупки или роскоши. Прогресс отмечайте вручную; цены в карточке фиксируются.</p><details data-fold-ignore><summary>Как вести карточки</summary><p class="hint">Обновление рынка не меняет карточку. Для следующей партии нажмите «Повторить новой партией». Историю изготовлений и фактические сделки записывайте отдельно в соответствующих разделах.</p></details><p id="batch-card-status" class="hint" role="status" aria-live="polite"></p><div id="batch-card-list"></div>';
shipping.panel.prepend(panel);
const server=()=>shipping.state.server;
function message(text,bad=false){$('batch-card-status').textContent=text;$('batch-card-status').classList.toggle('negative',bad);}
const trip=document.createElement('details');trip.id='batch-itinerary';trip.dataset.foldIgnore='';trip.innerHTML='<summary>Получение и доставка по городам <span id="batch-itinerary-count"></span></summary><p class="hint">Все активные партии текущего сервера, независимо от поиска и фильтров. Показаны только уже отмеченные покупки и товары к перевозке. Для распределения по грузоподъёмности откройте «Планировщик рейсов» выше.</p><div id="batch-itinerary-list"></div>';$('batch-card-list').before(trip);
function renderItinerary(){
 window.BatchOperationsUI?.render();
 window.BatchOverlayHost?.changed();
 const routes=store?M.itinerary(store.snapshot().cards,server()):[];
 $('batch-itinerary-count').textContent='· '+routes.reduce((sum,r)=>sum+r.lines.length,0)+' позиций';
 $('batch-itinerary-list').innerHTML=routes.map(route=>'<section class="batch-trip"><h3>'+esc(route.action)+' · '+esc(city(route.city))+(route.destination?' → '+esc(city(route.destination)):'')+'</h3>'+route.lines.map(line=>'<div class="batch-task"><span><b>'+esc(line.item)+' · '+fmt(line.quantity)+' шт.</b><small>'+esc(line.cardName)+'</small></span><button type="button" class="button" data-batch-trip-open="'+esc(line.card)+'">Открыть партию</button></div>').join('')+'</section>').join('')||'<p class="hint">Пока нет отмеченных покупок к получению или забранных товаров к доставке.</p>';
}
function readUpdate(editor){return Object.fromEntries(['remaining','price','count','exactFee'].map(key=>{const input=editor.querySelector('[data-update-value="'+key+'"]');return [key,input.value===''&&key==='exactFee'?null:input.value===''?NaN:input.valueAsNumber];}));}
function previewUpdate(editor){
 if(!editor||!store)return;
 const output=editor.querySelector('[data-update-preview]'),card=store.snapshot().cards.find(c=>c.uid===editor.dataset.batchId);
 if(!output||!card||card.server!==server())return;
 const estimate=M.preview(card,editor.dataset.batchSide,editor.dataset.updateEditor,readUpdate(editor));
 output.classList.toggle('negative',!estimate.valid||estimate.loss);
 if(!estimate.valid){output.textContent=estimate.error;return;}
 output.textContent='Комиссия обновлений: '+fmt(estimate.fee)+' серебра. '+(estimate.profit===null?'Прибыль пока неизвестна: заполните цены и прочие затраты.':'Прибыль после обновлений: '+fmt(estimate.profit)+' · изменение: '+(estimate.delta>0?'+':'')+fmt(estimate.delta)+'. '+(estimate.unlimited?'При нулевой комиссии повторения по той же цене не уменьшают прибыль.':'До убытка: '+(estimate.maxRepeats===1000?'до 1000 (лимит сценария)':estimate.maxRepeats)+' таких обновлений с тем же остатком и ценой.'));
}
function field(card,row,side,prop,label,max,value,type='number'){
 return `<label class="field" >${label}<input data-batch-field="${prop}" data-batch-id="${esc(card.uid)}" ${row?`data-batch-row="${esc(row.uid)}" data-batch-side="${side}"`:''} type="${type}" ${type==='number'?`min="${prop==='otherCost'?-1e15:0}" max="${max}" step="${prop==='price'||prop==='otherCost'||prop==='rate'||prop==='tax'?'any':'1'}"`:''} ${type==='text'?`maxlength="${prop==='name'?160:500}"`:''} value="${esc(value??'')}" ${prop==='price'?'placeholder="Цена неизвестна"':''}></label>`;
}
function updates(card,row,side){
 const r=M.reprice(row),filled=side==='buy'?row.bought:row.sold,last=row.updates.at(-1),remaining=Math.min(row.quantity-filled,last?.remaining??row.quantity);
 return `<details data-fold-ignore class="batch-updates" data-batch-fold="${row.uid}-updates"><summary>Обновления ордера · ${fmt(r.fees)} серебра дополнительно</summary><p class="hint">Каждое обновление: оставшееся количество × новая цена × комиссия. Повторения считаются по тем же цене и остатку. Начальная постановка учтена отдельно; налог продажи применяется один раз при продаже. Можно ввести точную комиссию из игры за одно обновление.</p><ol class="batch-update-list">${row.updates.map((change,index)=>`<li><span>Остаток ${fmt(change.remaining)} × ${fmt(change.price)} · ${change.count} обновл. · комиссия ${fmt((change.exactFee??M.setup(change.remaining,change.price,row.rate))*change.count)}</span><button type="button" class="button" data-batch-remove-update="${row.uid}" data-batch-side="${side}" data-batch-id="${card.uid}" data-update-index="${index}">Убрать из расчёта</button></li>`).join('')}</ol><div class="batch-update-editor" data-update-editor="${row.uid}" data-batch-side="${side}" data-batch-id="${card.uid}"><div class="batch-fields"><label class="field">Остаток на момент обновления<input data-update-value="remaining" type="number" min="1" max="${last?.remaining??row.quantity}" step="1" value="${remaining||''}"></label><label class="field">Новая цена / шт.<input data-update-value="price" type="number" min="0.000001" step="any" value="${r.price??''}"></label><label class="field">Число одинаковых обновлений<input data-update-value="count" type="number" min="1" max="1000" step="1" value="1"></label><label class="field">Комиссия за одно обновление, серебро<input data-update-value="exactFee" type="number" min="0" step="any" placeholder="По проценту комиссии"></label></div><p class="hint batch-update-preview" data-update-preview role="status" aria-live="polite">Укажите параметры обновления для предварительного расчёта.</p><button type="button" class="button" data-batch-add-update="${row.uid}" ${row.updates.length>=50?'disabled':''}>Учесть обновление</button></div></details>`;
}
function rowView(card,row,side){
 const buy=side==='buy',done=buy?row.bought:row.sold;
 return `<article class="batch-city-row" data-card-city="${esc(row.city)}"><div class="section-heading"><div><h4>${esc(city(row.city))}</h4><span>${esc(row.name)} · ${fmt(row.quantity)} шт.</span></div><span>${buy?'Осталось купить':'Осталось продать'} ${fmt(row.quantity-done)} шт.</span></div><progress max="${row.quantity}" value="${done}" aria-label="${esc((buy?'Куплено':'Продано')+' '+row.name+' '+city(row.city))}"></progress><div class="batch-fields">${buy?field(card,row,side,'bought','Куплено',row.quantity,row.bought)+field(card,row,side,'ordered','В действующих ордерах',row.quantity-row.bought,row.ordered||0)+field(card,row,side,'picked','Забрано',row.bought,row.picked)+(card.destination?field(card,row,side,'delivered','Доставлено',row.picked,row.delivered):''):field(card,row,side,'sold','Продано',row.quantity,row.sold)}${field(card,row,side,'price','Начальная цена / шт.',1e15,row.price)}<label class="field">Город<select data-batch-field="city" data-batch-id="${card.uid}" data-batch-row="${row.uid}" data-batch-side="${side}">${['',...M.cities].map(c=>`<option value="${esc(c)}" ${row.city===c?'selected':''}>${esc(city(c))}</option>`).join('')}</select></label></div><div class="batch-order-options"><label class="refining-check"><input type="checkbox" data-batch-field="order" data-batch-id="${card.uid}" data-batch-row="${row.uid}" data-batch-side="${side}" ${row.order?'checked':''}> ${buy?'Ордер покупки':'Ордер продажи'}</label>${row.order?field(card,row,side,'rate','Постановка и обновление, %',100,row.rate):''}${!buy?field(card,row,side,'tax','Налог продажи, %',100,row.tax):''}</div>${row.order?updates(card,row,side):'<p class="hint">Мгновенная покупка или прямая продажа: комиссия обновления ордера не применяется.</p>'}</article>`;
}
function cardView(card){
 const s=M.summary(card),purchase=card.kind==='purchase',craft=card.kind==='craft';
 const count=craft?`Получены материалы: ${s.readyRows} / ${card.buys.length} позиций`:`Куплено ${fmt(s.bought)} / ${fmt(card.quantity)} шт.`;
 return `<details data-fold-ignore class="batch-card" data-batch-card="${card.uid}" ${card.uid===selected?'open':''}><summary><span><span class="tag">${labels[card.kind]}</span> <strong>${esc(card.name)}</strong><small>${fmt(card.quantity)} шт. · ${esc(s.status)}${card.archived?' · Архив':''}</small></span><span class="batch-card-profit">${purchase?'Бюджет с обновлениями':'Прибыль по сценарию'}<b class="${s.profit!==null&&s.profit<0?'negative':''}">${fmt(purchase?s.cost:s.profit)}</b></span></summary><div class="batch-card-body"><div class="batch-stage-summary"><span>${count}</span><span>${craft?'Изготовлено '+fmt(card.made)+' / '+fmt(card.quantity):'Забрано '+fmt(s.picked)}${!purchase?' · Продано '+fmt(s.sold):''}</span></div>${!craft&&s.quantity?`<progress max="${s.quantity}" value="${s.bought}" aria-label="Прогресс закупки партии"></progress>`:''}<div class="batch-next"><h4>Следующие действия</h4>${s.tasks.length?s.tasks.map(t=>`<div class="batch-task"><span>${esc(t.action)} ${fmt(t.quantity)} шт. · ${esc(t.item)} · ${esc(city(t.city))}${t.destination?' → '+esc(city(t.destination)):''}</span><button type="button" class="button" data-batch-task="${t.field}" data-batch-id="${card.uid}" data-batch-row="${t.uid}">${t.field==='picked'?'Отметить получение':'Отметить доставку'}</button></div>`).join(''):s.complete?'<p>Все этапы партии отмечены.</p>':craft&&card.made===card.quantity?'<p>Отметьте продажи готовой партии.</p>':craft&&s.readyRows===card.buys.length?'<p>Отметьте изготовление продукции.</p>':!purchase&&s.delivered===card.quantity?'<p>Товар доставлен. Отметьте продажи.</p>':'<p>Отметьте исполнение закупок по городам.</p>'}</div><div class="batch-economics"><div><span>Закупка, постановка и обновления</span><b>${fmt(s.purchase)}</b></div><div><span>Обновления покупок</span><b>${fmt(s.buyFees)}</b></div>${!purchase?`<div><span>Обновления продаж</span><b>${fmt(s.saleFees)}</b></div><div><span>Прибыль без обновлений</span><b>${fmt(s.baseProfit)}</b></div><div><span>Прибыль с обновлениями и новыми ценами</span><b class="${s.profit!==null&&s.profit<0?'negative':''}">${fmt(s.profit)}</b></div>`:''}</div><p class="hint">Серебро. Это расчёт для всей партии по зафиксированным ценам и сценарию обновлений, а не фактический доход. Неизвестная цена остаётся неизвестной. Повторная покупка товара при обновлении не прибавляется; учитываются изменение цены остатка и новая комиссия.</p><details data-fold-ignore data-batch-fold="${card.uid}-settings"><summary>Название, заметка и пункт доставки</summary><div class="batch-fields">${field(card,null,'','name','Название партии',0,card.name,'text')}<label class="field">Доставить в<select data-batch-field="destination" data-batch-id="${card.uid}">${['',...M.cities.filter(c=>c!=='Black Market')].map(c=>`<option value="${c}" ${card.destination===c?'selected':''}>${c||'Доставка не требуется'}</option>`).join('')}</select></label>${field(card,null,'','note','Заметка',0,card.note,'text')}${field(card,null,'','otherCost','Дорога, производство и прочие затраты, серебро',1e15,card.otherCost)}</div><p class="hint">Прочие затраты не включают закупку и комиссии ордеров. Доход журналов уменьшает их; отрицательная сумма допустима. Пустое поле означает, что затраты пока неизвестны.</p></details><h3>${craft?'Материалы по городам':'Закупки по городам'}</h3>${card.buys.map(row=>rowView(card,row,'buy')).join('')||'<p class="hint">В расчёте нет материалов для покупки.</p>'}${craft?`<div class="batch-production">${field(card,null,'','made','Изготовлено продукции, шт.',card.quantity,card.made)}</div>`:''}${card.sales.length?'<h3>Продажи по городам</h3>'+card.sales.map(row=>rowView(card,row,'sale')).join(''):''}<div class="batch-card-actions"><button type="button" class="button" data-batch-duplicate="${card.uid}">Повторить новой партией</button><button type="button" class="button" data-batch-archive="${card.uid}">${card.archived?'Вернуть из архива':'В архив'}</button></div><p class="hint">Создано ${esc(new Date(card.created).toLocaleString('ru-RU'))}. Изменения полей сохраняются после ввода и выхода из поля.</p></div></details>`;
}
function render(){
 renderItinerary();
 const tabs=window.Workspace?.snapshot(),active=tabs?.tabs.find(t=>t.id===tabs.active),visible=active?.target.id==='batches';
 panel.hidden=!visible;shipping.panel.classList.toggle('batch-board-only',!!visible);
 $('batch-kind').value=filter;$('batch-archive').checked=archive;$('batch-search').value=query;$('batch-stage').value=stage;
 const opened=new Set([...panel.querySelectorAll('[data-batch-card][open]')].map(n=>n.dataset.batchCard)),folds=new Set([...panel.querySelectorAll('[data-batch-fold][open]')].map(n=>n.dataset.batchFold));
 const cards=store?.snapshot().cards.filter(c=>M.matches(c,{server:server(),kind:filter,archive,query,stage})).reverse()||[];
 $('batch-match-count').textContent='Найдено: '+cards.length;
 $('batch-server').textContent={europe:'Европа',west:'Америка',east:'Азия'}[server()]||server();
 $('batch-card-list').innerHTML=cards.map(cardView).join('')||'<p class="empty">Карточек по выбранным условиям пока нет. Нажмите «Вести партию» в нужном расчёте.</p>';
 if(!cards.length&&(query.trim()||stage!=='all'||filter!=='all'))$('batch-card-list').innerHTML='<p class="empty">По выбранным условиям партий нет. Измените поиск, этап или нажмите «Сбросить фильтры».</p>';
 for(const detail of panel.querySelectorAll('[data-batch-card]'))if(opened.has(detail.dataset.batchCard))detail.open=true;
 for(const detail of panel.querySelectorAll('[data-batch-fold]'))if(folds.has(detail.dataset.batchFold))detail.open=true;
 if(error)message(error,true);
}
function refreshCard(uid){
 renderItinerary();
 const card=store.snapshot().cards.find(c=>c.uid===uid),node=panel.querySelector('[data-batch-card="'+uid+'"]');if(!node||!card){render();return;}
 if(!M.matches(card,{server:server(),kind:filter,archive,query,stage})){render();return;}
 const template=document.createElement('template');template.innerHTML=cardView(card);const fresh=template.content.firstElementChild;
 for(const selector of [':scope>summary','.batch-stage-summary','.batch-next','.batch-economics'])node.querySelector(selector).innerHTML=fresh.querySelector(selector).innerHTML;
 const main=node.querySelector(':scope>.batch-card-body>progress'),newMain=fresh.querySelector(':scope>.batch-card-body>progress');if(main&&newMain)main.value=newMain.value;
 const rows=[...node.querySelectorAll('.batch-city-row')],newRows=[...fresh.querySelectorAll('.batch-city-row')];
 rows.forEach((row,index)=>{
  const replacement=newRows[index];row.dataset.cardCity=replacement.dataset.cardCity;row.querySelector('.section-heading').innerHTML=replacement.querySelector('.section-heading').innerHTML;row.querySelector('progress').value=replacement.querySelector('progress').value;
  for(const input of row.querySelectorAll('[data-batch-field]')){const twin=replacement.querySelector('[data-batch-field="'+input.dataset.batchField+'"]');if(twin?.hasAttribute('max'))input.max=twin.max;if(twin&&document.activeElement!==input){if(input.type==='checkbox')input.checked=twin.checked;else input.value=twin.value;}}
  const details=row.querySelector('.batch-updates'),newDetails=replacement.querySelector('.batch-updates');
  if(details&&newDetails){details.querySelector('summary').textContent=newDetails.querySelector('summary').textContent;details.querySelector('.batch-update-list').innerHTML=newDetails.querySelector('.batch-update-list').innerHTML;for(const input of details.querySelectorAll('[data-update-value]'))if(!input.dataset.dirty&&document.activeElement!==input)input.value=newDetails.querySelector('[data-update-value="'+input.dataset.updateValue+'"]').value;}
 });
 for(const editor of node.querySelectorAll('.batch-updates[open] [data-update-editor]'))previewUpdate(editor);
}
function show(uid){
 if(window.Workspace){const opened=Workspace.open(Workspace.registry.section('batches'),{context:{server:store?.snapshot().cards.find(c=>c.uid===uid)?.server||$('server').value}});if(!opened||!shipping.active())return false;}else CraftApp.navigate('shipping');
 selected=uid||selected;filter='all';query='';stage='all';$('batch-kind').value='all';render();panel.hidden=false;shipping.panel.classList.add('batch-board-only');QuickNavigation?.reveal(panel);(uid?panel.querySelector('[data-batch-card="'+uid+'"]'):panel)?.scrollIntoView({block:'start',behavior:'instant'});return true;
}
function add(seed){if(!store)throw Error(error);const card=store.add(seed);if(!show(card.uid))return card;message('Карточка сохранена. Отмечайте фактический прогресс по городам.');return card;}
function purchaseSeed(){const x=BuyOrderUI.snapshot();if(!x.plan.valid||!x.plan.rows.length)throw Error('Сначала полностью распределите закупку по городам.');const item=PRICE_CATALOG.find(r=>r.id===x.state.item);return {kind:'purchase',server:shipping.state.server,item:x.state.item,name:item?.name||x.state.item,quality:x.state.quality,quantity:Number(x.state.quantity),buys:x.plan.rows.map(r=>({city:r.city,quantity:r.quantity,price:r.price,order:true,rate:Number(x.state.fee)}))};}
function craftSeed(){
 const x=CraftApp.snapshot(),r=x.result,c=x.config;if(!Number.isSafeInteger(r.amount)||r.amount<1)throw Error('Укажите положительное целое количество продукции.');
 const buys=r.bill.flatMap(m=>m.buy>0?(m.allocation?m.allocation.rows.filter(p=>p.quantity>0).map(p=>({item:m.id,name:ALBION_DATA.names[m.id]||m.id,city:M.cities.includes(p.city)?p.city:'',quantity:p.quantity,price:p.price>0?p.price:null})): [{item:m.id,name:ALBION_DATA.names[m.id]||m.id,city:M.cities.includes(m.city)?m.city:'',quantity:m.buy,price:m.price>0?m.price:null}]):[]);
 const saleRows=r.sales?.rows.filter(row=>row.quantity>0)||[{city:c.sellCity,quantity:r.amount,price:Number(c.salePrice)}],discount=c.saleMode==='discord'?1-Number(c.discount)/100:1;
 return {kind:'craft',server:x.server,item:x.recipe.id,name:x.recipe.name,quality:Number(c.quality)||1,quantity:r.amount,destination:M.cities.includes(c.craftCity)?c.craftCity:'',buys,sales:saleRows.map(row=>({city:M.cities.includes(row.city)?row.city:'',quantity:row.quantity,price:row.price>0?row.price*discount:null,order:c.saleMode==='sell',rate:Number(c.setup),tax:c.saleMode==='discord'?0:Number(c.tax)})),otherCost:r.missing||!x.placeReady?null:r.netProductionCost-buys.reduce((sum,row)=>sum+row.quantity*(row.price||0),0)};
}
function luxurySeed(){const x=LuxuryUI.snapshot(),c=x.config,r=x.result;if(!r.valid)throw Error('Заполните цены, количество и грузоподъёмность для перевозки роскоши.');return {kind:'luxury',server:x.server,item:x.item.id,name:x.item.name,quantity:r.quantity,quality:1,destination:c.sellCity,buys:[{city:c.buyCity,quantity:r.quantity,price:Number(c.buyPrice),order:c.buyMode==='order',rate:Number(c.setup)}],sales:[{city:c.sellCity,quantity:r.quantity,price:Number(c.sellPrice),order:c.sellMode==='sell',rate:Number(c.setup),tax:Number(c.tax)}],otherCost:r.transport};}
function sourceButton(id,parent,seed){const button=document.createElement('button');button.id=id;button.type='button';button.className='button primary';button.textContent='Вести партию';const status=document.createElement('p');status.className='hint';status.setAttribute('role','status');let busy=false;button.onclick=()=>{if(busy)return;busy=true;try{const card=add(seed());status.textContent='Карточка «'+card.name+'» сохранена в «Торговля → Партии». Обновления ордеров учитываются в карточке.';}catch(e){status.textContent=e.message;}setTimeout(()=>{busy=false;},500);};parent.append(button,status);}
sourceButton('batch-from-orders',$('buy-order-planner').querySelector('.section-heading'),purchaseSeed);
sourceButton('batch-from-craft',document.querySelector('.craft-actions-grid'),craftSeed);
sourceButton('batch-from-luxury',$('art-export').parentElement,luxurySeed);
const all=document.createElement('button');all.type='button';all.className='button';all.textContent='Карточки партий';all.id='ship-batch-cards';all.onclick=()=>show();$('ship-new-batch').parentElement.append(all);
$('batch-kind').onchange=()=>{filter=$('batch-kind').value;render();};$('batch-archive').onchange=()=>{archive=$('batch-archive').checked;render();};
$('batch-search').oninput=()=>{query=$('batch-search').value;render();};$('batch-stage').onchange=()=>{stage=$('batch-stage').value;render();};
$('batch-clear-filters').onclick=()=>{filter='all';query='';stage='all';archive=false;render();};
panel.addEventListener('change',event=>{
 const input=event.target.closest('[data-batch-field]');if(!input||!store)return;
 const id=input.dataset.batchId,prop=input.dataset.batchField;
 try{store.update(id,card=>{if(card.server!==server())throw Error('Сервер карточки изменился.');const row=input.dataset.batchRow?(input.dataset.batchSide==='buy'?card.buys:card.sales).find(r=>r.uid===input.dataset.batchRow):card;if(!row)throw Error('Строка не найдена.');row[prop]=input.type==='checkbox'?input.checked:input.type==='number'?(input.value===''&&['price','otherCost'].includes(prop)?null:input.value===''?NaN:input.valueAsNumber):input.value;});input.removeAttribute('aria-invalid');message('Изменения сохранены.');if(prop==='order'||prop==='destination')render();else refreshCard(id);}catch(e){input.setAttribute('aria-invalid','true');message(e.message,true);if(input.type==='checkbox')input.checked=!input.checked;}
});
panel.addEventListener('input',event=>{if(event.target.dataset.updateValue){event.target.dataset.dirty='true';previewUpdate(event.target.closest('[data-update-editor]'));}});
panel.addEventListener('toggle',event=>{if(event.target.matches('.batch-updates[open]'))previewUpdate(event.target.querySelector('[data-update-editor]'));},true);
panel.addEventListener('click',event=>{
 if(!store)return;
 try{
  const tripButton=event.target.closest('[data-batch-trip-open]');if(tripButton){const card=store.snapshot().cards.find(c=>c.uid===tripButton.dataset.batchTripOpen);if(card?.server!==server())throw Error('Сервер карточки изменился.');show(card.uid);return;}
  const task=event.target.closest('[data-batch-task]');
  if(task){store.update(task.dataset.batchId,card=>{if(card.server!==server())throw Error('Сервер карточки изменился.');const row=card.buys.find(r=>r.uid===task.dataset.batchRow);if(!row)throw Error('Строка не найдена.');if(task.dataset.batchTask==='picked')row.picked=row.bought;else if(task.dataset.batchTask==='delivered')row.delivered=row.picked;else throw Error('Неизвестное действие.');});refreshCard(task.dataset.batchId);message('Отметка сохранена. При необходимости количество можно исправить в строке города.');}
  const archiveButton=event.target.closest('[data-batch-archive]'),duplicate=event.target.closest('[data-batch-duplicate]'),addButton=event.target.closest('[data-batch-add-update]'),remove=event.target.closest('[data-batch-remove-update]');
  if(archiveButton){store.update(archiveButton.dataset.batchArchive,c=>{if(c.server!==server())throw Error('Сервер карточки изменился.');c.archived=!c.archived;});message('Архив обновлён. Карточку можно вернуть через «Показать архив».');render();}
  if(duplicate){const original=store.snapshot().cards.find(c=>c.uid===duplicate.dataset.batchDuplicate);if(original?.server!==server())throw Error('Сервер карточки изменился.');const card=store.duplicate(original.uid);selected=card.uid;filter='all';query='';stage='all';archive=false;render();message('Создана новая партия. Прогресс и обновления ордеров обнулены.');}
  if(addButton||remove){const editor=addButton?.closest('[data-update-editor]'),id=editor?.dataset.batchId||remove.dataset.batchId,side=editor?.dataset.batchSide||remove.dataset.batchSide,uid=addButton?.dataset.batchAddUpdate||remove.dataset.batchRemoveUpdate;
   store.update(id,card=>{if(card.server!==server())throw Error('Сервер карточки изменился.');const row=(side==='buy'?card.buys:card.sales).find(r=>r.uid===uid);if(!row)throw Error('Ордер не найден.');if(remove)row.updates.splice(Number(remove.dataset.updateIndex),1);else{const read=key=>{const input=editor.querySelector('[data-update-value="'+key+'"]');return input.value===''&&key==='exactFee'?null:input.value===''?NaN:input.valueAsNumber;};row.updates.push({remaining:read('remaining'),price:read('price'),count:read('count'),exactFee:read('exactFee')});}});render();message('Расходы и прибыль пересчитаны с учётом обновлений.');
  }
 }catch(e){message(e.message,true);}
});
document.addEventListener('workspacechange',event=>{if(event.detail?.navigation){render();if(shipping.active()&&Workspace.snapshot().tabs.find(t=>t.id===Workspace.snapshot().active)?.target.id==='batches')requestAnimationFrame(()=>QuickNavigation.reveal(panel));}});
document.addEventListener('ledgerchange',()=>{if(shipping.active())render();});
window.BatchCards={show,add,store,render,purchaseSeed,craftSeed,luxurySeed,snapshot:()=>store?.snapshot()};render();
})();
